from sklearn.isotonic import IsotonicRegression

def features(t):
    return [[t.self_conf, float(t.schema_ok), float(t.tool_ok),
             t.evidence_coverage, float(t.samples_agree)]]

calibrator = IsotonicRegression(out_of_bounds='clip')
# calibrator.fit(X_train, y_correct)

def route(t, cost_error, cost_human):
    if not t.schema_ok or not t.tool_ok:
        return 'human', 1.0, 'hard_gate'
    p_err = 1.0 - float(calibrator.predict(features(t))[0])
    if p_err * cost_error > cost_human:
        return 'human', p_err, 'loss_gate'
    return 'auto', p_err, 'pass'

from fastapi import FastAPI, Request
from fastapi.responses import StreamingResponse
import asyncio, json

app = FastAPI()

def sse(event: str, data: dict, seq: int) -> str:
    body = json.dumps(data, ensure_ascii=False)
    return f"id: {seq}\nevent: {event}\ndata: {body}\n\n"

@app.post("/agent/stream")
async def agent_stream(req: Request, body: ChatIn):
    async def gen():
        seq, message_id = 0, new_id()
        try:
            async with llm.stream(body.messages) as stream:
                async for chunk in stream:
                    if await req.is_disconnected():
                        raise asyncio.CancelledError
                    seq += 1
                    if chunk.type == "token":
                        yield sse("token", {"text": chunk.text}, seq)
                    elif chunk.type == "tool_call":
                        yield sse("tool_start", {"name": chunk.name}, seq)
            seq += 1
            yield sse("done", {"message_id": message_id, "status": "ok"}, seq)
        except asyncio.CancelledError:
            await persist_partial(message_id, seq)
            raise

    return StreamingResponse(
        gen(), media_type="text/event-stream",
        headers={"X-Accel-Buffering": "no", "Cache-Control": "no-cache"},
    )

RRF_K = 60

def rrf_fuse(*rankings, k=RRF_K, top_n=60):
    scores = {}
    for ranking in rankings:
        for rank, doc_id in enumerate(ranking):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank + 1)
    return [d for d, _ in sorted(scores.items(), key=lambda x: -x[1])[:top_n]]

async def retrieve(query, tenant, top_k=6):
    flt = {"tenant": tenant}
    dense, sparse = await asyncio.gather(
        vdb.search(await embed(query), limit=80, flt=flt),
        bm25.search(query, limit=80, flt=flt),
    )
    fused = rrf_fuse([c.id for c in dense], [c.id for c in sparse])
    try:
        ranked = await asyncio.wait_for(reranker.rank(query, fused[:60]), timeout=0.6)
        picked = [c.id for c in ranked[:top_k]]
    except (asyncio.TimeoutError, RerankError):
        metrics.inc("rerank_fallback")
        picked = fused[:top_k]
    return [await expand_to_parent(cid) for cid in picked]

import anyio
from fastapi import FastAPI, Depends

app = FastAPI()
LIMIT = anyio.CapacityLimiter(8)          # 独立于 AnyIO 默认 40 token


def legacy_client():                       # 同步依赖也占线程池，禁止做网络调用
    return LegacySDK(timeout=5)


@app.post("/answer")
async def answer_bad(q: str, c=Depends(legacy_client)):
    return c.ask(q)                        # 直接阻塞事件循环，最坏情况


async def blocking_ask(q: str) -> str:     # 同步 SDK 包一层，必须有 timeout
    return LegacySDK(timeout=5).ask(q)


@app.post("/answer-ok")
async def answer_ok(q: str):
    try:
        async with LIMIT:                  # 按下游容量做背压
            return await anyio.to_thread.run_sync(blocking_ask, q)
    except TimeoutError:
        return {"code": "upstream_timeout"}   # 快速失败优于排队
